export default async function plan({ body, values, sheet, acknowledge, resolution }, ctx) {
  const id = String(body.submissionId || ""),
    stage = String(body.stage || "");
  if (!id || !["signup", "survey"].includes(stage) || !/^[\w -]+$/.test(sheet))
    throw Error("Invalid registration");
  const header = [
      "execution_id",
      "date",
      "email",
      "first_name",
      "last_name",
      "job_level",
      "job_function",
      "country_region",
      "product_experience",
      "product_goals",
      "enrol_betatesters",
    ],
    rows = values ?? [];
  if (header.some((v, i) => (rows[0] ?? [])[i] !== v))
    throw Error("Configure required sheet headers");
  const matches = [];
  for (let i = 1; i < rows.length; i++) if (rows[i][0] === id) matches.push(i + 1);
  if (matches.length > 1) throw Error("Duplicate registration ID");
  const key = "newsletter:" + id + ":" + stage + ":sheet",
    old = await ctx.state.get(key),
    skip = { write: false, update: false, key, range: "Sheet1!A1:K1", values: [] };
  if (old?.status === "done") return skip;
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending sheet write " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return skip;
    }
  }
  let row;
  if (stage === "signup") {
    if (matches.length) throw Error("Registration already exists");
    const email = String(body.email || "")
      .trim()
      .toLowerCase();
    if (!email) throw Error("Missing email");
    row = [id, String(body.date || ""), email, "", "", "", "", "", "", "", ""];
  } else {
    if (!matches.length) throw Error("Missing registration");
    row = [...(rows[matches[0] - 1] ?? [])];
    while (row.length < 11) row.push("");
    const s = body.survey ?? {};
    for (const [i, k] of [
      [3, "first_name"],
      [4, "last_name"],
      [5, "job_level"],
      [6, "job_function"],
      [7, "country_region"],
      [8, "product_experience"],
      [9, "product_goals"],
      [10, "enrol_betatesters"],
    ])
      row[i] = String(s[k] ?? "");
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    write: true,
    update: matches.length === 1,
    key,
    range: "'" + sheet + "'!A" + (matches[0] ?? 1) + ":K" + (matches[0] ?? 1),
    values: [row],
  };
}

