export default async function plan({ body, acknowledge, resolution }, ctx) {
  const key = "newsletter:" + body.submissionId + ":slack",
    old = await ctx.state.get(key),
    skip = { send: false, key, text: "" };
  if (old?.status === "done") return skip;
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending Slack notification " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return skip;
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return {
    send: true,
    key,
    text: String(body.email || "").trim() + " just signed up to the newsletter!",
  };
}

